# src-tauri/src/main.rs
#[tauri::command]
async fn generate_local(prompt: String) -> Result<String, String> {
    // Invoke local Ollama / llama.cpp HTTP API at 127.0.0.1:11434
    let client = reqwest::Client::new();
    let res = client.post('http://127.0.0.1:11434/api/generate')
        .json(&serde_json::json!({ 'model': 'llama3.2:3b', 'prompt': prompt, 'stream': false }))
        .send().await.map_err(|e| e.to_string())?;
    Ok(res.text().await.map_err(|e| e.to_string())?)
}
